const w = $('Set the window').first().json;
const real = (items) => items.map((i) => i.json).filter((r) => r.order_id !== undefined && r.order_id !== null && r.order_id !== '');
const cmp = $('Compare on order_id');
const from = Date.parse(w.from), to = Date.parse(w.to);
// A destination row created outside the day belongs to another day's check (the 2-hour margin reads a little past midnight)
const otherDay = (r) => { const t = Date.parse(r.order_created_at); return Number.isFinite(t) && (t < from || t >= to); };

const source = real($('Read the source').all());
const destination = real($('Read the destination').all()).filter((r) => !otherDay(r));
const sourceIds = new Set(source.map((r) => String(r.order_id)));

const missing = real(cmp.all(0)).map((r) => String(r.order_id)).sort();
const extra = real(cmp.all(3)).filter((r) => !otherDay(r))
  .map((r) => ({ order_id: String(r.order_id), why: sourceIds.has(String(r.order_id)) ? 'second copy' : 'not in the source' }))
  .sort((x, y) => x.order_id.localeCompare(y.order_id));
const different = cmp.all(2).map((i) => i.json)
  .map((d) => ({ order_id: String(d.keys.order_id), fields: Object.fromEntries(Object.entries(d.different).map(([k, v]) => [k, [v.inputA, v.inputB]])) }))
  .sort((x, y) => x.order_id.localeCompare(y.order_id));

const lines = [
  'Daily count check for ' + w.day + '.',
  'Source: ' + source.length + ' orders. Destination: ' + destination.length + ' rows (read up to 02:00 today).',
  '',
];
if (source.length === 0) lines.push('The source returned no orders for this day. If that is unusual, check the source connection or its trigger.', '');
if (destination.length === 0 && source.length > 0) lines.push('The destination returned no rows for this day.', '');
if (!missing.length && !extra.length && !different.length) lines.push('Nothing missing, nothing extra, nothing different.');
if (missing.length) lines.push('Missing at the destination (' + missing.length + '): ' + missing.join(', '));
if (extra.length) lines.push('Only at the destination (' + extra.length + '): ' + extra.map((e) => e.order_id + ' (' + e.why + ')').join(', '));
if (different.length) {
  lines.push('Different (' + different.length + '):');
  for (const d of different) lines.push('- ' + d.order_id + ': ' + Object.entries(d.fields).map(([k, [a, b]]) => k + ' ' + a + ' -> ' + b).join(', '));
}
lines.push('', 'This message is sent every day, also when everything matches. If it does not arrive, the check itself has stopped.');

return [{ json: {
  day: w.day, source_count: source.length, destination_count: destination.length,
  missing, extra, different,
  subject: 'Count check ' + w.day + ': ' + missing.length + ' missing, ' + extra.length + ' extra, ' + different.length + ' different',
  text: lines.join('\n'),
} }];
